#include <tuple>
#include "jsd/project.hpp"
#include <fstream>
#include <mutex>
#include <cstring>
#include <atomic>
namespace jsd::project {
uint64_t nextTerrainRevision(){static std::atomic<uint64_t> n{1};return n.fetch_add(1);}
namespace {
float smooth(float a,float b,float t){t=rf::clamp((t-a)/(b-a));return t*t*(3-2*t);}

template<class T,class F>T sample(const TerrainData &t,float x,float z,const std::vector<T>&data,T fallback,F lerp){if(data.empty()||x<t.originX||z<t.originZ||x>t.originX+t.width||z>t.originZ+t.depth)return fallback;float u=std::clamp((x-t.originX)/t.width*(t.resolution-1),0.f,float(t.resolution-1)),v=std::clamp((z-t.originZ)/t.depth*(t.resolution-1),0.f,float(t.resolution-1));unsigned a=std::min(unsigned(u),t.resolution-2),b=std::min(unsigned(v),t.resolution-2);return lerp(lerp(data[b*t.resolution+a],data[b*t.resolution+a+1],u-a),lerp(data[(b+1)*t.resolution+a],data[(b+1)*t.resolution+a+1],u-a),v-b);}
}
float TerrainData::baseHeight(float x,float z)const{return offset+gain*(generator=="waves"?(std::sin(x*.05f)+std::cos(z*.06f))*2:0);}
float TerrainData::height(float x,float z)const{return baseHeight(x,z)+sample(*this,x,z,heights,0.f,[](float a,float b,float t){return rf::mix(a,b,t);});}
Color TerrainData::color(float x,float z)const{return sample(*this,x,z,colors,Color{},[](Color a,Color b,float t){return Color{rf::mix(a.r,b.r,t),rf::mix(a.g,b.g,t),rf::mix(a.b,b.b,t),rf::mix(a.a,b.a,t)};});}
void TerrainData::resize(unsigned n){if(n<17||n>1025)throw std::runtime_error("Terrain grid must have 17-1025 samples per edge");auto old=*this;resolution=n;heights.resize(size_t(n)*n);colors.resize(size_t(n)*n);for(unsigned z=0;z<n;z++)for(unsigned x=0;x<n;x++){float X=originX+width*x/(n-1),Z=originZ+depth*z/(n-1);heights[z*n+x]=old.height(X,Z)-old.baseHeight(X,Z);colors[z*n+x]=old.color(X,Z);}revision=nextTerrainRevision();}
void TerrainData::brush(float x,float z,float radius,float strength,int mode,float target,Color tint){if(!std::isfinite(x+z+radius+strength+target)||radius<=0||mode<0||mode>5)throw std::runtime_error("Invalid terrain brush");if(heights.empty())resize(resolution);auto old=heights;int x0=std::max(0,int((x-radius-originX)/width*(resolution-1))),x1=std::min(int(resolution-1),int(std::ceil((x+radius-originX)/width*(resolution-1))));int z0=std::max(0,int((z-radius-originZ)/depth*(resolution-1))),z1=std::min(int(resolution-1),int(std::ceil((z+radius-originZ)/depth*(resolution-1))));
 for(int Z=z0;Z<=z1;Z++)for(int X=x0;X<=x1;X++){float px=originX+width*X/(resolution-1),pz=originZ+depth*Z/(resolution-1),distance=std::hypot(px-x,pz-z);if(distance>radius)continue;float weight=1-smooth(0,radius,distance),amount=std::abs(strength)*weight;size_t i=size_t(Z)*resolution+X;
 if(mode==0||mode==1)heights[i]+=amount*(mode==0?1:-1);else if(mode==2){float sum=0;int count=0;for(int dz=-1;dz<=1;dz++)for(int dx=-1;dx<=1;dx++){int a=std::clamp(X+dx,0,int(resolution)-1),b=std::clamp(Z+dz,0,int(resolution)-1);float ax=originX+width*a/(resolution-1),bz=originZ+depth*b/(resolution-1);sum+=old[b*resolution+a]+baseHeight(ax,bz);count++;}heights[i]=rf::mix(old[i]+baseHeight(px,pz),sum/count,std::clamp(amount,0.f,1.f))-baseHeight(px,pz);}else if(mode==3)heights[i]=rf::mix(heights[i]+baseHeight(px,pz),target,std::clamp(amount,0.f,1.f))-baseHeight(px,pz);else if(mode==4){auto &c=colors[i];float a=std::clamp(amount,0.f,1.f);c={rf::mix(c.r,tint.r,a),rf::mix(c.g,tint.g,a),rf::mix(c.b,tint.b,a),1};}else{heights[i]=rf::mix(heights[i],0,std::clamp(amount,0.f,1.f));colors[i]={1,1,1,1};}}
 revision=nextTerrainRevision();
}
Json TerrainData::json()const{Json j={{"enabled",enabled},{"generator",generator},{"resolution",resolution},{"width",width},{"depth",depth},{"originX",originX},{"originZ",originZ},{"gain",gain},{"offset",offset},{"seed",seed},{"material",material},{"heights",heights},{"colors",Json::array()}};for(auto c:colors)j["colors"].push_back({c.r,c.g,c.b,c.a});return j;}
TerrainData TerrainData::fromJson(const Json&j){TerrainData t;t.enabled=j.value("enabled",false);t.generator=j.value("generator","flat");t.resolution=j.value("resolution",129u);t.width=j.value("width",320.f);t.depth=j.value("depth",260.f);t.originX=j.value("originX",-160.f);t.originZ=j.value("originZ",-80.f);t.gain=j.value("gain",1.f);t.offset=j.value("offset",0.f);t.seed=j.value("seed",38004u);t.material=j.value("material",0u);t.heights=j.value("heights",std::vector<float>{});for(auto&c:j.value("colors",Json::array()))t.colors.push_back({c.at(0),c.at(1),c.at(2),c.at(3)});t.validate();return t;}
void TerrainData::validate()const{if(resolution<17||resolution>1025||!std::isfinite(width+depth+originX+originZ+gain+offset)||width<=0||depth<=0||(!heights.empty()&&heights.size()!=size_t(resolution)*resolution)||(!colors.empty()&&colors.size()!=size_t(resolution)*resolution)||(generator!="flat"&&generator!="waves"))throw std::runtime_error("Invalid terrain grid");for(float h:heights)if(!std::isfinite(h)||std::abs(h)>10000)throw std::runtime_error("Invalid terrain height");for(auto c:colors)for(float f:{c.r,c.g,c.b,c.a})if(!std::isfinite(f)||f<0||f>4)throw std::runtime_error("Invalid terrain paint");}
const Mesh& geometry(const Object&o){return o.sharedMesh?*o.sharedMesh:o.mesh;}
void makeUnique(Object&o){if(o.sharedMesh){o.mesh=*o.sharedMesh;o.sharedMesh.reset();o.meshRef.clear();}if(o.materialOverride>=0){for(auto&f:o.mesh.faces)f.material=o.materialOverride;o.materialOverride=-1;}}
bool active(const Document&d,const Object&o,float time){if(!o.visible)return false;bool visible=true;if(o.components.contains("visibility")){for(auto&key:o.components["visibility"]){if(key.at(0).get<float>()>time)break;visible=key.at(1);}}if(!visible)return false;return !o.parent||active(d,*d.find(o.parent),time);}
unsigned materialAt(const Object&o,unsigned mat,float time){unsigned result=o.materialOverride>=0?unsigned(o.materialOverride):mat;if(o.components.contains("materialKeys"))for(auto&k:o.components["materialKeys"]){if(k.at(0).get<float>()>time)break;result=k.at(1);}return result;}
std::vector<gfx::Vertex> meshVertices(const Mesh&m){std::vector<gfx::Vertex>out;for(auto&[mat,v]:triangles(m))out.insert(out.end(),v.begin(),v.end());return out;}
void writeMesh(const Mesh&m,const std::filesystem::path&path){validate(m);std::ofstream f(path,std::ios::binary);if(!f)throw std::runtime_error("Cannot write project mesh");uint32_t header[4]={0x4d44534a,1,uint32_t(m.vertices.size()),uint32_t(m.faces.size())};f.write((char*)header,sizeof header);for(auto&v:m.vertices)f.write((char*)&v,sizeof v);for(auto&face:m.faces){uint32_t n=face.vertices.size(),mat=face.material;f.write((char*)&n,4);f.write((char*)&mat,4);f.write((char*)face.vertices.data(),face.vertices.size()*4);}uint32_t smooth=m.smooth;f.write((char*)&smooth,4);if(!f)throw std::runtime_error("Project mesh write failed");}
using FileAssetKey=std::tuple<std::filesystem::path,std::uintmax_t,std::filesystem::file_time_type>;
FileAssetKey fileAssetKey(const std::filesystem::path& path){return {std::filesystem::weakly_canonical(path),std::filesystem::file_size(path),std::filesystem::last_write_time(path)};}
std::shared_ptr<Mesh> readMesh(const std::filesystem::path&path){static std::mutex mutex;static std::map<FileAssetKey,std::weak_ptr<Mesh>>cache;auto key=fileAssetKey(path);std::lock_guard lock(mutex);if(auto p=cache[key].lock())return p;std::ifstream f(path,std::ios::binary);uint32_t h[4]{};f.read((char*)h,sizeof h);if(!f||h[0]!=0x4d44534a||h[1]!=1||h[2]>3000000||h[3]>1000000)throw std::runtime_error("Invalid project mesh header");auto m=std::make_shared<Mesh>();m->vertices.resize(h[2]);for(auto&v:m->vertices)f.read((char*)&v,sizeof v);for(unsigned i=0;i<h[3];i++){uint32_t n=0,mat=0;f.read((char*)&n,4);f.read((char*)&mat,4);if(n<3||n>4096)throw std::runtime_error("Invalid project polygon");Face face;face.material=mat;face.vertices.resize(n);f.read((char*)face.vertices.data(),n*4);m->faces.push_back(std::move(face));}uint32_t smooth=0;f.read((char*)&smooth,4);if(!f)throw std::runtime_error("Truncated project mesh");m->smooth=smooth;validate(*m);cache[key]=m;return m;}
}
namespace jsd::project {
const std::vector<Key>&motionKeys(const Object&o){return o.motion.sharedKeys?*o.motion.sharedKeys:o.motion.keys;}
void editableKeys(Object&o){if(o.motion.sharedKeys){o.motion.keys=*o.motion.sharedKeys;o.motion.sharedKeys.reset();o.motion.clipFile.clear();}if(o.motion.relative&&!o.motion.keys.empty()){auto delta=matrix(o.transform)*rf::inverse(matrix(o.motion.keys.front().transform));for(auto &k:o.motion.keys)k.transform=decompose(delta*matrix(k.transform));o.motion.relative=false;}}
void writeClip(std::span<const Key>keys,const std::filesystem::path&path){std::ofstream f(path,std::ios::binary);uint32_t h[3]={0x4344534a,1,uint32_t(keys.size())};f.write((char*)h,sizeof h);for(auto&k:keys){auto q=orientation(k.transform);float row[12]={k.time,k.transform.position.x,k.transform.position.y,k.transform.position.z,q.x,q.y,q.z,q.w,k.transform.scale.x,k.transform.scale.y,k.transform.scale.z,float(k.interpolation)};f.write((char*)row,sizeof row);}if(!f)throw std::runtime_error("Cannot write project clip");}
std::shared_ptr<std::vector<Key>>readClip(const std::filesystem::path&path){static std::mutex lock;static std::map<FileAssetKey,std::weak_ptr<std::vector<Key>>>cache;auto key=fileAssetKey(path);std::lock_guard guard(lock);if(auto p=cache[key].lock())return p;std::ifstream f(path,std::ios::binary);uint32_t h[3]{};f.read((char*)h,sizeof h);if(!f||h[0]!=0x4344534a||h[1]!=1||h[2]>100000)throw std::runtime_error("Invalid project clip");auto out=std::make_shared<std::vector<Key>>();out->reserve(h[2]);for(unsigned i=0;i<h[2];i++){float r[12]{};f.read((char*)r,sizeof r);for(float v:r)if(!std::isfinite(v))throw std::runtime_error("Nonfinite clip sample");if(r[0]<0||(!out->empty()&&r[0]<=out->back().time))throw std::runtime_error("Invalid clip time order");Transform t;t.position={r[1],r[2],r[3]};t.quaternion=rf::normalize({r[4],r[5],r[6],r[7]});t.rotationDegrees=euler(*t.quaternion);t.scale={r[8],r[9],r[10]};out->push_back({r[0],t,int(r[11])});}if(!f)throw std::runtime_error("Truncated project clip");cache[key]=out;return out;}
}
